import{_ as a,o as r,c as d,a8 as t}from"./chunks/framework.CiGKN4gy.js";const b=JSON.parse('{"title":"2.x.x","description":"","frontmatter":{"title":"2.x.x","lang":"en"},"headers":[],"relativePath":"changes/2_x_x.md","filePath":"changes/2_x_x.md","lastUpdated":1790353258000}'),o={name:"changes/2_x_x.md"};function i(l,e,h,c,n,f){return r(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjIyLngueCUyMiUyQyUyMmxhbmclMjIlM0ElMjJlbiUyMiUyQyUyMmRhdGUlMjIlM0ExNzkwMzUzMjU4MDAwJTdE"},[...e[0]||(e[0]=[t('<h1 id="change-log-2-x-x" tabindex="-1">Change Log (2.x.x) <a class="header-anchor" href="#change-log-2-x-x" aria-label="Permalink to &quot;Change Log (2.x.x)&quot;">​</a></h1><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><div class="tip custom-block"><p class="custom-block-title">What is a breaking change?</p><ul><li>The original configuration file may not work, for example, if a directive item is removed or renamed.</li><li>It may be necessary to update the build environment, such as installing new dependencies.</li></ul></div><h2 id="_2-1-1-2020-12-10" tabindex="-1">[2.1.1] - 2020-12.10 <a class="header-anchor" href="#_2-1-1-2020-12-10" aria-label="Permalink to &quot;[2.1.1] - 2020-12.10&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed a module startup failure error. The error message for this error is <code>nginx: [alert] could not open error log file: open() &quot;ngx_waf: /logs/error.log&quot; failed (2: No such file or directory)</code> (<a href="https://github.com/ADD-SP/ngx_waf/commit/0dfc46f2dfc7ed91977b501c868abf961966d4e1" target="_blank" rel="noreferrer">0dfc46f</a>).</li></ul><hr><h2 id="_2-1-0-2020-12-09" tabindex="-1">[2.1.0] - 2020-12-09 <a class="header-anchor" href="#_2-1-0-2020-12-09" aria-label="Permalink to &quot;[2.1.0] - 2020-12-09&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Compatible with the mainline version of NGINX (<a href="https://github.com/ADD-SP/ngx_waf/commit/f31f906b11fb00f54bfea504ca7c8c147a0be1d8" target="_blank" rel="noreferrer">f31f906</a> &amp; <a href="https://github.com/ADD-SP/ngx_waf/commit/7b4f897a4a332b43bf94de874f8ba8c3098aaee4" target="_blank" rel="noreferrer">65277d1</a>).</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><hr><h2 id="_2-0-2-2020-12-07" tabindex="-1">[2.0.2] - 2020-12-07 <a class="header-anchor" href="#_2-0-2-2020-12-07" aria-label="Permalink to &quot;[2.0.2] - 2020-12-07&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Fix for Anti Challenge Collapsar failing when <code>waf_mult_mount</code> is disabled (<a href="https://github.com/ADD-SP/ngx_waf/commit/048fe5c15863d9a3106387225774305aa5564726" target="_blank" rel="noreferrer">048fe5c</a>).</p></li><li><p>Fixed compile error caused by incorrect <code>#include</code> (<a href="https://github.com/ADD-SP/ngx_waf/commit/3fa298c6184618ea0cd6336783a4d7a2ed27469c" target="_blank" rel="noreferrer">3fa298c</a>).</p></li></ul><hr><h2 id="_2-0-1-2020-12-03" tabindex="-1">[2.0.1] - 2020-12-03 <a class="header-anchor" href="#_2-0-1-2020-12-03" aria-label="Permalink to &quot;[2.0.1] - 2020-12-03&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Instead of downloading the uthash dependency manually, you can install the system library with <code>yum install uthash-devel</code> or <code>apt-get install uthash-dev</code> (<a href="https://github.com/ADD-SP/ngx_waf/commit/7cfc94bc64fa4f2c29bdf3b24e21aeb1ba412054" target="_blank" rel="noreferrer">7cfc94b</a>).</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed a bug that failed to compile under CentOS/RHEL 6 or 7 that was caused by not properly preventing macro redefinitions (<a href="https://github.com/ADD-SP/ngx_waf/commit/28e1c8aca03375089c75df21c5db3c38013edde7" target="_blank" rel="noreferrer">28e1c8a</a> &amp; <a href="https://github.com/ADD-SP/ngx_waf/commit/566ae4a50f855674b256db84305a24e1b2a6bc6d" target="_blank" rel="noreferrer">566ae4a</a>).</li></ul><hr><h2 id="_2-0-0-2020-09-29" tabindex="-1">[2.0.0] - 2020-09-29 <a class="header-anchor" href="#_2-0-0-2020-09-29" aria-label="Permalink to &quot;[2.0.0] - 2020-09-29&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>We can compile the module with <code>--add-dynamic-module</code>. Thanks for <a href="https://github.com/dvershinin" target="_blank" rel="noreferrer">dvershinin</a>&#39;s work(<a href="https://github.com/ADD-SP/ngx_waf/pull/4" target="_blank" rel="noreferrer">https://github.com/ADD-SP/ngx_waf/pull/4</a>)。</li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p>Remove a default User-Agent rule that is <code>(?i)(? :Sogou web spider)</code>, as it will block non-malicious web spider(<a href="https://github.com/ADD-SP/ngx_waf/commit/827d4e5bc48894ff9147e49799d3a9656fe7dd8a" target="_blank" rel="noreferrer">827d4e5</a>).</p></li><li><p>Merge directives (<a href="https://github.com/ADD-SP/ngx_waf/commit/ba92cfd53ce78da8ff4ed22d2bc71a47de4cbe25" target="_blank" rel="noreferrer">ba92cfd</a>). These directives will be merged: <code>waf_check_ipv4</code>, <code>waf_check_url</code>, <code>waf_check_args</code>, <code>waf_check_ua</code>, <code>waf_check_referer</code>, <code>waf_check_cookie</code>, <code>waf_check_post</code>, <code>waf_check_cookie</code>, <code>waf_cc_deny</code>. The merged new directive is <code>waf_mode</code>, see <a href="https://github.com/ADD-SP/ngx_waf/blob/master/README-EN.md" target="_blank" rel="noreferrer">README</a>.</p></li></ul><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The blank lines in the rules can now be read correctly (<a href="https://github.com/ADD-SP/ngx_waf/commit/955cf2d240c4d66f815890e3ee9b88ccf906cf1d" target="_blank" rel="noreferrer">955cf2d</a>).</li></ul>',35)])])}const u=a(o,[["render",i]]);export{b as __pageData,u as default};
